  @override
  void initState() {
    super.initState();
    final recorder = widget.touchRecorder ??
        _acquisitionService.recordComparisonTouch;
    unawaited(recorder(widget.competitorKey));
  }

  _CompetitorInfo get _info => widget.info;
  bool get _hasImportSupport =>
      widget.competitorKey == 'notion' || widget.competitorKey == 'evernote';
  int get _withheldLegacyClaimCount =>
      1 + _info.painPoints.length + _info.features.length;
  List<CompetitorClaimEvidence> get _featureEvidence => widget.evidenceClaims
      .where((claim) => claim.claimType == CompetitorClaimType.feature)
      .toList(growable: false);
  List<CompetitorClaimEvidence> get _otherEvidence => widget.evidenceClaims
      .where((claim) => claim.claimType != CompetitorClaimType.feature)
      .toList(growable: false);
  // Legacy fallback copy remains available for editorial recovery, but it is
  // deny-by-default and never rendered without row-level evidence metadata.
  bool get _showLegacyClaims => false;

  List<MapEntry<String, _CompetitorInfo>> get _relatedCompetitors {
    final currentCategory = _categoryOf[widget.competitorKey];
    final seen = <String>{widget.competitorKey};
    final items = <MapEntry<String, _CompetitorInfo>>[];

    // 1. Same-category companies first (up to 3)
    if (currentCategory != null) {
      for (final key in _competitorInfo.keys) {
        if (items.length >= 3) break;
        if (_categoryOf[key] != currentCategory) continue;
        if (!seen.add(key)) continue;
        final info = _competitorInfo[key];
        if (info == null) continue;
        items.add(MapEntry(key, info));
      }
    }

    // 2. Featured companies to fill remaining slots
    for (final key in _featuredCompetitorKeys) {
      if (items.length >= 6) break;
      if (!seen.add(key)) continue;
      final info = _competitorInfo[key];
      if (info == null) continue;
      items.add(MapEntry(key, info));
    }

    // 3. Any others to reach 6
    for (final key in _competitorInfo.keys) {
      if (items.length >= 6) break;
      if (!seen.add(key)) continue;
      final info = _competitorInfo[key];
      if (info == null) continue;
      items.add(MapEntry(key, info));
    }

    return items;
  }

  String get _switchStepTitle =>
      _hasImportSupport ? '既存データをそのまま移行' : '${_info.name} から30秒で乗り換え開始';

  String get _switchStepBody => _hasImportSupport
      ? '${_info.name} のデータをインポートしながら、今の資産を崩さず移行できます。'
      : 'まずは無料で始めて、必要な作業だけを1か所に集約できます。';

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _pageBackground,
      body: Container(
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [
              _info.accentColor.withValues(alpha: 0.12),
              _pageBackground,
              _pageBackground,
            ],
          ),
        ),
        child: SafeArea(
          child: SingleChildScrollView(
            child: Column(
              children: [
                _buildBreadcrumb(context),
                _buildHero(context),
                _buildOutcomeCards(),
                _buildPainPoints(),
                _buildFeatureTable(),
                _buildSwitchPlan(context),
                _buildRelatedComparisons(context),
                ComparisonCtaPanel(
                  competitorName: _info.name,
                  accentColor: _info.accentColor,
                  hasImportSupport: _hasImportSupport,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildBreadcrumb(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.fromLTRB(24, 16, 24, 0),
      child: Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 1040),
          child: Wrap(
            spacing: 4,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              InkWell(
                onTap: () => Navigator.of(context).pushNamed('/'),
                borderRadius: BorderRadius.circular(6),
                child: const Padding(
                  padding: EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: Text(
                    '自分株式会社',
                    style: TextStyle(
                      fontSize: 12,
                      color: _textMuted,
                      height: 1.5,
                    ),
                  ),
                ),
              ),
              const Text(
                '/',
                style: TextStyle(fontSize: 12, color: _textMuted, height: 1.5),
              ),
              InkWell(
                onTap: () => Navigator.of(context).pushNamed('/competitors'),
                borderRadius: BorderRadius.circular(6),
                child: const Padding(
                  padding: EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                  child: Text(
                    '競合比較',
                    style: TextStyle(
                      fontSize: 12,
                      color: _textMuted,
                      height: 1.5,
                    ),
                  ),
                ),
              ),
              const Text(
                '/',
                style: TextStyle(fontSize: 12, color: _textMuted, height: 1.5),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 2),
                child: Text(
                  '${_info.emoji} ${_info.name}',
                  style: const TextStyle(
